import { Autocomplete, Box, Button, Checkbox, FormControlLabel, FormGroup, TextField } from '@mui/material';
import React, { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import MedicineCards from './MedicineCards';
import { callAll } from '@chakra-ui/react/dist/types/utils';
import callApi from '../../Services/callApi';
import { IDisease, INurseForm, useNurseForm } from '../../Context/NurseFormContext';
import Swal from 'sweetalert2';
import DiseaseList from './DiseaseList';
import { Add, Save } from '@mui/icons-material';
import DiseaseModal from './DiseaseModal';
import DiseaseAccordion from './DiseaseAccordion';
import { useNavigate } from 'react-router-dom';
import { IInventoryTransactionOut } from '../../Context/InventoryTransactionContext';

type FormData = {
    no: number;
    create_at: string;
    employee_id: string;
    significant_characteristic: string;
    disease_group: string;
    create_by: number;
    status: string;
    disease_group_name: string;
    updated_at?: string;
    updated_by?: number;
    position: string;
    department: string;
    fullname: string
};


interface IEmpOption {
    code: string
    label: string
}

export default function DiseaseForm() {
    const navigate = useNavigate();
    const { nurseForm, setNurseForm, diseaseList, setDiseaseList, medicine } = useNurseForm();
    const [employeeList, setEmployeeList] = useState<any[]>();
    const [empOption, setEmpOption] = useState<IEmpOption[]>([]);
    const { register, handleSubmit, setValue, getValues } = useForm<INurseForm>();
    const [diseaseModal, setDiseaseModal] = useState<boolean>(false);
    const [activeStep, setActiveStep] = useState(0);

    useEffect(() => {
        // console.log(diseaseList);
    }, [diseaseList])
    useEffect(() => {
        onLoadEmp();
    }, [])

    const onSubmit = (data: INurseForm) => {
        console.log(data)
        setNurseForm({ ...data })
        if (diseaseList.length <= 0) {
            Swal.fire('โปรดระบุอาการ', '', 'warning')
            return;
        }
        handleSave({ ...data, disease: diseaseList, medichine: medicine });
    };

    const onLoadEmp = async () => {
        const result = await callApi.get('/employee?type=list')
        if (result.data?.data) {
            setEmployeeList(result.data?.data);
            onMapEmp(result.data?.data)
        }
    }

    const onMapEmp = async (data: any[]) => {

        var emp = data.map<IEmpOption>((item: any) => ({
            code: item.employee_id,
            label: item.employee_id + ' | ' + item.first_name + ' ' + item.last_name
        }));

        setEmpOption(emp)
    }

    const handleEmpChange = async (name: string, value: any) => {
        console.log(name, value);
        if (!value) {
            setValue('fullname', '')
            setValue('employee_id', '')
            return;
        }
        var itemValue = value.label.split('|')
        setValue('fullname', itemValue[1].toString().trim() ?? null)
        setValue('employee_id', itemValue[0].toString().trim() ?? null)

        const emp = employeeList?.find(item => item.employee_id == itemValue[0].toString().trim())
        if (emp) {
            setValue('department', emp.department)
            setValue('position', emp.position)
        }
    }
    const handleDiseaseChange = async (name: string, valueArr: any) => {
        console.log(name, valueArr);
        if (!valueArr) {
            return;
        }
        var item = valueArr.map((value: any) => {
            var itemValue = value.label.split('|')
            return { disease_group_name: itemValue[1].toString().trim() ?? null, disease_group: itemValue[0].toString().trim() ?? null }
        })
        setDiseaseList(item);
    }

    const handleSave = async (data: any) => {


        const res = await callApi.post('/initial_treatment_record?type=create', data)
        if (res?.data?.status == 'success') {
            Swal.fire('Success', res.data?.message, 'success');

            if (Array.isArray(data.disease)) {
                data?.disease.forEach((item: any, i: number) => {
                    var newInventoryTransactionOut: IInventoryTransactionOut[] = item?.medicine?.map((item: any) => {
                        return {
                            source_type: 'NR',
                            source_id: res?.data?.data,
                            item_id: item.id,
                            quantity: item.quantity,
                            unit: item.unit
                        }
                    })
                    if (newInventoryTransactionOut) {
                        callApi.post('/inventory_transaction?type=out', newInventoryTransactionOut);

                    }
                    if (data?.disease.length == i + 1) {
                        navigate('/nurse')
                    }
                })

                // if (resultInventoryTransaction?.data?.status != 'success') {
                //     Swal.fire('Create Inventory Transaction Error', '', 'error');
                // }
                // 
            } else {
                navigate('/nurse')
            }

        } else {
            Swal.fire('Error', res.data?.message, 'error');
        }
    }

    const submitManually = () => {
        handleSubmit(onSubmit)(); // ต้องใส่ () อีกชุด
    };
    // const handleNext = () => setActiveStep((prev) => prev + 1);
    // const handleBack = () => setActiveStep((prev) => prev - 1);
    const onOpenDiseaseModal = () => setDiseaseModal(true);
    const onCloseDiseaseModal = () => setDiseaseModal(false);
    return (<>
        <DiseaseModal onClose={onCloseDiseaseModal} open={diseaseModal} onOpen={onOpenDiseaseModal} />
        <form >
            <Box sx={{ display: 'flex', flex: 'row', justifyContent: 'center', mb: 2, flexWrap: 'wrap', gap: 2 }}>

                <Autocomplete
                    {...register('employee_id')}
                    fullWidth
                    options={empOption}
                    getOptionLabel={(option) => option.label}
                    onChange={(_, value) => handleEmpChange('fullname', value)}
                    renderInput={(params) => (
                        <TextField {...params} label="👤 Employee ID" margin="normal" fullWidth
                            // onBlur={handleChange} 
                            name='fullname' />
                    )}
                />
                <TextField required fullWidth variant="outlined" type="text" {...register('fullname')} label="🔡 Fullname" sx={{ display: 'none' }} />
                <TextField required fullWidth variant="outlined" type="text" {...register('position')} label="🔡 Position" disabled defaultValue='-' />
                <TextField required fullWidth variant="outlined" type="text" {...register('department')} label="🔡 Department" disabled defaultValue={'-'} />
                {/* <TextField required fullWidth variant="outlined" type="text" {...register('significant_characteristic')} label="🔡 Significant Characteristic" /> */}

                {/* <Autocomplete
                    multiple
                    limitTags={3}
                    id="multiple-limit-tags"
                    options={illnessOptions}
                    getOptionLabel={(option) => option.label}
                    defaultValue={[]}
                    onChange={(_, value) => handleDiseaseChange('', value)}
                    renderInput={(params) => (
                        <TextField {...params} label="Disease" placeholder="Favorites" />
                    )}
                    fullWidth
                /> */}
                <DiseaseAccordion />
                <div style={{ marginTop: 12, display: 'flex', gap: 4, width: '100%' }}>
                    <FormGroup>
                        <FormControlLabel {...register('sleep')} control={<Checkbox name='sleep' />} label="นอนพักสังเกตุอาการ" />
                        <FormControlLabel {...register('hospital')} control={<Checkbox name='hospital' />} label="ส่งรักษาต่อที่โรงพยาบาล" />
                    </FormGroup>
                </div>
                <Button onClick={onOpenDiseaseModal} variant="outlined" size='large' startIcon={<Add />} fullWidth>
                    Add New Disease
                </Button>
                <Button variant="contained" color="primary" size="large" type='button' onClick={submitManually} >
                    Save
                </Button>
            </Box>
        </form>


    </>);
}
